code_sketch:
static pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t  cv = PTHREAD_COND_INITIALIZER;
static queue_t q;                          /* guarded state */

int q_take(item_t *out) {
    pthread_mutex_lock(&m);
    while (queue_empty(&q))                /* predicate re-checked in a loop */
        pthread_cond_wait(&cv, &m);        /* atomically release + park */
    *out = queue_pop(&q);                  /* guarded action on locked state */
    pthread_mutex_unlock(&m);
    return 0;                              /* caller owns the item */
}

